--так будет лучше......
local HEAVY_BLADE = "axe|scythe|labrys|sword|slayer|machete|chainsaw|spear|taiga|rebel"

function MH.GuessFams(cls)
	local wstore = weapons.GetStored(cls)
	if cls != "weapon_hg_fists" and !(wstore and wstore.Category == "Weapons - Melee") then return end

	if cls == "weapon_hg_fists" then return { "BlackJack", "Bat" } end

	local low = string.lower(cls)
	if string.find(low, "extinguisher") then return { "Bat", "Hammer" } end	-- огнетушитель бьют

	if wstore and wstore.DamageType == DMG_SLASH then
		if wstore.TwoHanded or string.find(low, HEAVY_BLADE) then return { "Cleaver", "IceAxe" } end
		return { "Knife", "Cleaver" }
	end

	if wstore and wstore.TwoHanded then return { "Bat" } end
	return { "BlackJack", "Hammer" }
end

